#!/usr/bin/env python3
"""Archive a validated Church campaign; dry-run unless --write is explicit."""
import argparse
import difflib
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys

ROOT = Path('/Users/0x1/Documents/htdocs/altbak.pub')
COMPILER = ROOT.parent / 'gopurs/gopurs'
WORK = ROOT / 'var/benchmark/go-church-20261125'
BASELINE = WORK / 'compiler-before/manifest.json'


def digest(data):
    return hashlib.sha256(data).hexdigest()


def artifact(path):
    path = Path(path)
    data = path.read_bytes()
    return {'sha256': digest(data), 'size_bytes': len(data), 'text': data.decode('utf-8')}


def git(*args):
    return subprocess.check_output(['git', '-C', str(COMPILER), *args], text=True)


def final_proofs(campaign, proofs, expected_variants):
    old_sha = campaign['core_manifest']['plan'][0]['executable_sha256']
    new_sha = campaign['core_manifest']['plan'][1]['executable_sha256']
    c_sha = campaign['frozen_reference']['c_build']['manifest']['binary_sha256']
    matches = {}
    for path in [proofs / 'before-inputs/manifest.json', proofs / 'after-inputs/manifest.json']:
        manifest = json.loads(path.read_text())
        if not isinstance(manifest, dict):
            raise ValueError(f'Invalid final input proof manifest: {path}')
        if manifest.get('binary_sha256') not in [old_sha, new_sha]:
            continue
        if manifest.get('cases') != expected_variants or manifest.get('opaque_calls_per_action') != 1 or manifest.get('c_binary_sha256') != c_sha:
            raise ValueError(f'Incorrect final input proof: {path}')
        source = Path(manifest['generated_source'])
        if digest(source.read_bytes()) != manifest['generated_sha256']:
            raise ValueError(f'Changed generated source for input proof: {source}')
        override = path.parent / 'opaque-override.go'
        if digest(override.read_bytes()) != manifest['override_sha256']:
            raise ValueError(f'Changed input override: {override}')
        stdout = (path.parent / 'stdout.txt').read_text()
        if len(stdout.splitlines()) != expected_variants or (path.parent / 'stderr.txt').read_text():
            raise ValueError(f'Incomplete final input proof: {path}')
        matches[manifest['binary_sha256']] = {'path': str(path.parent.relative_to(proofs)),
                                             'stdout': stdout,
                                             'inputs': json.loads((path.parent / 'inputs.json').read_text())}
    if set(matches) != {old_sha, new_sha}:
        raise ValueError('Both final App14 binaries require their runtime-input proof')
    if matches[old_sha]['stdout'] != matches[new_sha]['stdout'] or matches[old_sha]['inputs'] != matches[new_sha]['inputs']:
        raise ValueError('Input variant results differ between the final before/after builds')
    return {'before': matches[old_sha]['path'], 'after': matches[new_sha]['path'],
            'variants_per_build': expected_variants, 'opaque_calls_per_action': 1,
            'same_outputs_and_inputs': True, 'c_binary_sha256': c_sha}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--campaign', type=Path, default=WORK / 'campaign/results.json')
    parser.add_argument('--validation-summary', type=Path, required=True,
                        help='Root-approved final test/e2e outcomes; unsuccessful intermediate logs remain identified')
    parser.add_argument('--proofs', type=Path, default=WORK / 'proofs')
    parser.add_argument('--output', type=Path, default=ROOT / 'docs/benchmark-results/2026-11-25-go-church.json')
    parser.add_argument('--write', action='store_true')
    args = parser.parse_args()
    campaign = json.loads(args.campaign.read_text())
    for path, expected in campaign['compiler_snapshot']['files_sha256'].items():
        if digest(Path(path).read_bytes()) != expected:
            raise ValueError(f'Compiler changed after the campaign: {path}')
    for path, expected in campaign['frozen_reference']['source_sha256'].items():
        if digest((ROOT / path).read_bytes()) != expected:
            raise ValueError(f'Frozen benchmark/reference changed before archiving: {path}')
    baseline_manifest = json.loads(BASELINE.read_text())
    for group in ['files', 'sources']:
        for item in baseline_manifest[group].values():
            if digest(Path(item['path']).read_bytes()) != item['sha256']:
                raise ValueError('Frozen original compiler changed')
    names = set(git('ls-files', '--cached', '--others', '--exclude-standard').splitlines())
    names |= set(baseline_manifest['sources'])
    names = sorted(name for name in names if
        (name.startswith(('src/', 'runtime/', 'tools/', 'docs/')) or name in
         ['CHANGELOG.md', 'README.md', 'package.json', 'package-lock.json',
          'spago.yaml', 'spago.lock', 'bootstrap-sources.json']) and
        Path(name).suffix in {'.purs', '.go', '.js', '.rs', '.mjs', '.md', '.json', '.yaml', '.lock'})
    changed, patch, before_sources, after_sources = [], '', {}, {}
    for name in names:
        old_entry = baseline_manifest['sources'].get(name)
        old = Path(old_entry['path']).read_text() if old_entry else ''
        current = COMPILER / name
        new = current.read_text() if current.is_file() else ''
        if old == new:
            continue
        changed.append(name)
        if old_entry:
            before_sources[name] = artifact(old_entry['path'])
        after_sources[name] = artifact(current) if current.is_file() else {'deleted': True}
        patch += ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True),
                                             fromfile='a/' + name, tofile='b/' + name))
    if not changed:
        raise ValueError('No compiler source changes from the frozen working baseline')
    logs = {}
    for pattern in ['gopurs-church-*.log', 'altbak-church-*.log']:
        for path in sorted(Path('/tmp').glob(pattern)):
            if path.name.startswith(('gopurs-church-state-', 'altbak-church-state-')):
                continue
            item = artifact(path)
            # This describes each log, not the aggregate final validation status.
            counts = {label: int(value) for label, value in re.findall(r'(?m)^ℹ (tests|pass|fail|skipped) (\d+)$', item['text'])}
            if counts:
                item['reported_counts'] = counts
                item['phase_status'] = 'intermediate_failure' if counts.get('fail') else 'passed'
            logs[path.name] = item
    final_validation = json.loads(args.validation_summary.read_text())
    evidence = final_proofs(campaign, args.proofs, final_validation['runtime_variants']['per_final_binary'])
    proof_files = {}
    for path in sorted(args.proofs.rglob('*')):
        if not path.is_file():
            continue
        relative = path.relative_to(args.proofs)
        final_inputs = relative.parts[0] in {'before-inputs', 'after-inputs'}
        excerpt = relative.parent == Path('production-generated') and (
            path.suffix == '.go' or path.name == 'manifest.json')
        regression = relative.parts[0].startswith('regression-') and path.suffix in {
            '.json', '.go', '.py', '.stdout', '.stderr'}
        assembly = relative.parent == Path('.') and path.suffix == '.txt' and (
            'production' in path.name or path.name.endswith('-church-loop-assembly.txt'))
        if not (final_inputs or excerpt or assembly or regression):
            continue
        if path.name == 'opaque-override.go':
            data = path.read_bytes()
            proof_files[str(relative)] = {
                'sha256': digest(data), 'size_bytes': len(data),
                'text_omitted': 'Large generated overlay; the patch, script and exact source/overlay hashes are retained.'}
        else:
            proof_files[str(relative)] = artifact(path)
    script_dir = Path(__file__).parent
    scripts = {name: artifact(script_dir / name) for name in ['measure-pair.py', 'archive.py', 'freeze.json']}
    proof_script = Path('/tmp/altbak-church-input-proof.py')
    scripts[proof_script.name] = artifact(proof_script)
    # The script hash is recorded by the completed campaign itself.
    if scripts['measure-pair.py']['sha256'] != campaign['wrapper_sha256']:
        raise ValueError('Measurement wrapper changed after the campaign')
    archive = {
        'date': '2026-11-25', 'archived_at_utc': datetime.now(timezone.utc).isoformat(),
        'campaign': campaign,
        'compiler': {'baseline_head': baseline_manifest['head'], 'baseline_kind': 'frozen working tree, including uncommitted changes', 'head_at_archive': git('rev-parse', 'HEAD').strip(),
                     'status_at_archive': git('status', '--porcelain'),
                     'baseline_manifest': baseline_manifest,
                     'measured_snapshot': campaign['compiler_snapshot'],
                     'diff_from_baseline': {'sha256': digest(patch.encode()), 'text': patch},
                     'before_sources': before_sources, 'changed_sources': after_sources},
        'validation': {'final_summary': final_validation, 'summary_source': artifact(args.validation_summary),
                       'campaign': campaign['validation'], 'runtime_input_proofs': evidence,
                       'logs': logs,
                       'note': 'Intermediate unsuccessful test logs are retained. Final outcomes are stated separately.'},
        'proofs': {'scripts': scripts, 'runtime_inputs': proof_files,
                   'reference_note': 'C sources, C binary and archived C medians are unchanged; C/JS were not remeasured.'},
    }
    serialized = json.dumps(archive, ensure_ascii=False, indent=2, allow_nan=False) + '\n'
    print(json.dumps({'archive_bytes': len(serialized.encode()), 'sources': changed,
                      'validation_logs': list(logs), 'proof_files': len(proof_files),
                      'runtime_input_proofs': evidence, 'output': str(args.output),
                      'writing': args.write}, indent=2))
    if args.write:
        if args.output.exists():
            raise ValueError('Refusing to overwrite an existing dated archive')
        args.output.write_text(serialized)
        print('Archive SHA-256: ' + digest(args.output.read_bytes()))


if __name__ == '__main__':
    main()

